import type { FeedConfig, FeedItem, ScraperHelpers } from "@rss-agentic/core"
import * as cheerio from "cheerio"

export async function fetchFeed(config: FeedConfig, helpers: ScraperHelpers): Promise<FeedItem[]> {
  // Fetch the listing page — it's a Webflow SSR site so plain fetch works
  const listHtml = await fetch(config.url).then(r => r.text())
  const $ = cheerio.load(listHtml)

  const itemEls = $('.blog_cms_wrap.w-dyn-list > .w-dyn-items > .w-dyn-item')
  const items: Array<{
    title: string
    url: string
    dateText: string
  }> = []

  itemEls.each((_i, el) => {
    const card = $(el)
    const title = card.find('.card_blog_title.u-text-style-h6').text().trim()
    const dateText = card.find('.u-text-style-caption.u-foreground-tertiary.u-mb-1-5').first().text().trim()
    const href = card.find('a[href*="/blog/"]').first().attr('href') || ''
    const url = href.startsWith('http') ? href : `https://claude.com${href}`
    if (title && url) {
      items.push({ title, url, dateText })
    }
  })

  // Fetch every detail page in parallel, extracting imageUrl and contentHtml
  const detailPromises = items.map(async (item) => {
    try {
      const html = await fetch(item.url).then(r => r.text())
      const $d = cheerio.load(html)

      // imageUrl: first <meta property="og:image"> (skip the generic fallback that follows)
      let imageUrl: string | undefined
      const ogImageEl = $d('meta[property="og:image"]').first()
      const ogContent = ogImageEl.attr('content')
      if (ogContent && !ogContent.includes('og_claude-generic')) {
        imageUrl = ogContent
      }

      // contentHtml: full inner HTML of .u-rich-text-blog
      let contentHtml: string | undefined
      const bodyEl = $d('.u-rich-text-blog').first()
      if (bodyEl.length > 0) {
        const html = bodyEl.html()
        if (html && html.trim().length > 0) {
          contentHtml = html
        }
      }

      // Parse the date
      const publishedAt = new Date(item.dateText).toISOString()

      return {
        id: item.url,
        title: item.title,
        url: item.url,
        publishedAt,
        source: config.slug,
        imageUrl,
        contentHtml,
      } satisfies FeedItem
    } catch (err) {
      // Graceful degradation: return item with basic fields only
      return {
        id: item.url,
        title: item.title,
        url: item.url,
        publishedAt: new Date(item.dateText).toISOString(),
        source: config.slug,
      } satisfies FeedItem
    }
  })

  const feedItems = await Promise.all(detailPromises)
  return feedItems
}
